package org.peirs.service;
import java.util.*;
public final class FinancialEngine { private FinancialEngine(){} public static Map<String,Object> calculate(double investment,double revenue,double annualCost,int years,double rate){if(investment<=0||years<1||revenue<0||annualCost<0||rate<0||rate>1)throw new IllegalArgumentException("Financial inputs must be valid and investment positive");double net=revenue-annualCost,npv=-investment,pv=0;for(int y=1;y<=years;y++){double discounted=net/Math.pow(1+rate,y);npv+=discounted;pv+=revenue/Math.pow(1+rate,y);}double roi=(net*years-investment)/investment*100;double payback=net>0?investment/net:Double.POSITIVE_INFINITY;double bcr=pv/investment;double irr=irr(investment,net,years);Map<String,Object> m=new LinkedHashMap<>();m.put("investment",investment);m.put("annualNetCashFlow",net);m.put("npv",round(npv));m.put("irr",Double.isFinite(irr)?round(irr*100):null);m.put("roi",round(roi));m.put("paybackYears",Double.isFinite(payback)?round(payback):null);m.put("bcr",round(bcr));m.put("profitabilityIndex",round((npv+investment)/investment));m.put("viable",npv>0);return m;} private static double irr(double i,double cf,int years){double lo=-.9,hi=5;for(int n=0;n<200;n++){double mid=(lo+hi)/2,sum=-i;for(int y=1;y<=years;y++)sum+=cf/Math.pow(1+mid,y);if(sum>0)lo=mid;else hi=mid;}return (lo+hi)/2;} private static double round(double n){return Math.round(n*100.0)/100.0;} }
